import pathlib,sys,json,time,numpy as np,torch
P=pathlib.Path(__file__).resolve().parent;sys.path.insert(0,str(P));import core
T=time.perf_counter();c=core.Core();z=np.load(P.parent/'phase5/FROZEN_PATHS.npz');st=c.cast(z['q'][0,0]);target=c.cast(z['target'][0]);x,log=core.classical(c,st,target,2026104977);assert x.shape==(2,24,7) and torch.isfinite(x).all();nominal=[core.nominal_check(c,c.nom(xx,st),target) for xx in x]
# Finite difference of ACTIVE physical CVaR, not just inactive safe-fixture cost.
xx=c.cast(np.concatenate((z['control_points'][0,3:26],z['control_points'][0,-1:]),0)).requires_grad_(True);wrong=target.clone();wrong[:,3]+=c.cast([.03,0,0]);er=tuple(c.cast(v) for v in core.errors(4,2026104975,2));loss=c.tail(c.risk_losses(c.nom(xx,st),wrong,er),.1);grad=torch.autograd.grad(loss,xx)[0];eps=1e-5;xp=xx.detach().clone();xm=xp.clone();xp[-1,2]+=eps;xm[-1,2]-=eps;fp=c.tail(c.risk_losses(c.nom(xp,st),wrong,er,False),.1);fm=c.tail(c.risk_losses(c.nom(xm,st),wrong,er,False),.1);fd=(fp-fm)/(2*eps);assert abs(float(fd-grad[-1,2]))<1e-4
report={'pass':True,'classical_proposal_log':log,'old_fixture_nominal_checks':nominal,'baseline_geometry_shape_and_freepose_correct':True,'active_CVaR_FD':{'analytic':float(grad[-1,2]),'FD':float(fd),'error':float(abs(fd-grad[-1,2]))},'seconds':time.perf_counter()-T};(P/'BASELINE_QUALIFICATION.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report),flush=True)
